import "@tanstack/react-start/server-only"

import { drizzle } from "drizzle-orm/postgres-js"
import type { PostgresJsDatabase } from "drizzle-orm/postgres-js"
import postgres from "postgres"
import type { Sql } from "postgres"

import { getServerEnv } from "@/env"

export type Db = PostgresJsDatabase & { $client: Sql }

declare global {
  // Dev HMR re-evaluates this module; the global slot keeps one pool across reloads.
  var appDb: Db | undefined
}

/**
 * Pool size and the server-side guards come from `env`. The timeouts make a runaway query, a lock
 * wait or a transaction left open fail fast. Pool size is per process: size it against
 * `max_connections` / replicas. Behind a transaction-mode pooler add `prepare: false`.
 */
function createDb(): Db {
  const env = getServerEnv()
  const client = postgres(env.DATABASE_URL.reveal(), {
    max: env.DATABASE_POOL_SIZE,
    connect_timeout: 5,
    idle_timeout: 20,
    max_lifetime: 1800,
    connection: {
      application_name: env.DB_APPLICATION_NAME,
      statement_timeout: env.DB_STATEMENT_TIMEOUT_MS,
      lock_timeout: env.DB_LOCK_TIMEOUT_MS,
      idle_in_transaction_session_timeout: env.DB_IDLE_IN_TRANSACTION_TIMEOUT_MS,
    },
  })
  return drizzle(client, { casing: "snake_case" })
}

/** Cached on globalThis so Vite's dev HMR reuses one pool instead of leaking one per reload. */
export function getDb(): Db {
  globalThis.appDb ??= createDb()
  return globalThis.appDb
}

import { defineConfig } from "drizzle-kit"

export default defineConfig({
  out: "./drizzle",
  // One file per feature under schema/ (columns.ts, auth.ts, notes.ts, ...): items add files, never edit one.
  schema: "./src/lib/db/schema/*.ts",
  dialect: "postgresql",
  casing: "snake_case",
  dbCredentials: {
    // oxlint-disable-next-line typescript/no-non-null-assertion -- `drizzle-kit generate` needs no connection; commands that do fail with drizzle-kit's own error when this is unset.
    url: process.env.DATABASE_URL!,
  },
})

/**
 * Apply the versioned SQL migrations in ./drizzle.
 * Prefer this over `drizzle-kit push` for anything shared or long-lived.
 * It reads only DATABASE_URL, so the production image can run it (Coolify `migrate` service).
 */
import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"
import postgres from "postgres"

async function main(url: string) {
  console.info("migrate:", url.replace(/:[^:@/]+@/, ":***@"))
  const client = postgres(url, { max: 1, connect_timeout: 20 })
  try {
    await migrate(drizzle(client), { migrationsFolder: "./drizzle" })
    console.info("migrate ok")
  } finally {
    await client.end({ timeout: 5 })
  }
}

const url = process.env.DATABASE_URL
if (!url) {
  console.error("DATABASE_URL missing: add it to .env first")
  process.exit(1)
}
try {
  await main(url)
} catch (error) {
  console.error("migrate failed:", error instanceof Error ? error.message : String(error))
  process.exit(1)
}

/**
 * Apply the committed migrations in ./drizzle to production, after the same migrations ran on the
 * development database (DATABASE_URL). Without `--yes` it only lists what is pending.
 *
 *   bun run scripts/migrate-production.ts --production-url "$PRODUCTION_DATABASE_URL"        # dry listing
 *   bun run scripts/migrate-production.ts --production-url "$PRODUCTION_DATABASE_URL" --yes  # apply
 */
import { readFileSync } from "node:fs"
import { parseArgs } from "node:util"

import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"
import postgres from "postgres"

import { journalSchema, pendingTags, resolveProductionRun } from "@/lib/db/migrations"
import type { ProductionRun } from "@/lib/db/migrations"

function parseRun(): ProductionRun {
  const { values } = parseArgs({
    options: { "production-url": { type: "string" }, yes: { type: "boolean" } },
    strict: true,
  })
  return resolveProductionRun(values, process.env.DATABASE_URL)
}

async function main(run: ProductionRun) {
  const journal = journalSchema.parse(
    JSON.parse(readFileSync("./drizzle/meta/_journal.json", "utf8")),
  )
  const client = postgres(run.url, { max: 1, connect_timeout: 10 })
  try {
    const states = await client<
      { present: boolean }[]
    >`select to_regclass('drizzle.__drizzle_migrations') is not null as present`
    const applied = states.some((row) => row.present)
      ? await client<{ created_at: string }[]>`select created_at from drizzle.__drizzle_migrations`
      : []
    const pending = pendingTags(
      journal,
      applied.map((row) => Number(row.created_at)),
    )
    const target = new URL(run.url)
    console.info(
      JSON.stringify({
        target: `${target.hostname}/${target.pathname.slice(1)}`,
        applied: applied.length,
        pending,
      }),
    )

    if (pending.length === 0) console.info("nothing to apply")
    else if (!run.apply) console.info("dry run: pass --yes to apply")
    else {
      await migrate(drizzle(client), { migrationsFolder: "./drizzle" })
      console.info(`applied ${pending.length} migration(s)`)
    }
  } finally {
    await client.end({ timeout: 5 })
  }
}

let run: ProductionRun
try {
  run = parseRun()
} catch (error) {
  console.error(`migrate-production: ${error instanceof Error ? error.message : String(error)}`)
  process.exit(1)
}
try {
  await main(run)
} catch (error) {
  console.error(
    "migrate-production failed:",
    error instanceof Error ? error.message : String(error),
  )
  process.exit(1)
}

import { z } from "zod"

/** The part of drizzle's `meta/_journal.json` this guard reads. */
export const journalSchema = z.object({
  entries: z.array(z.object({ tag: z.string(), when: z.number() })),
})

export type Journal = z.infer<typeof journalSchema>

/** Journal entries whose timestamp is not in `drizzle.__drizzle_migrations` yet, in journal order. */
export function pendingTags(journal: Journal, appliedAt: readonly number[]): string[] {
  return journal.entries
    .filter((entry) => !appliedAt.includes(entry.when))
    .map((entry) => entry.tag)
}

export type ProductionRun = { url: string; apply: boolean }

/**
 * The production guard. Production is never implied by the environment: it takes an explicit
 * `--production-url <url>` that must differ from DATABASE_URL (the development database), and it
 * only applies migrations with `--yes`. Anything else is a dry listing.
 */
export function resolveProductionRun(
  args: { "production-url"?: string | undefined; yes?: boolean | undefined },
  developmentUrl: string | undefined,
): ProductionRun {
  const url = args["production-url"]
  if (!url)
    throw new Error("refusing to run: pass --production-url <url> to name the production database")
  if (!/^postgres(?:ql)?:\/\/.+/u.test(url))
    throw new Error("--production-url must be a postgres:// or postgresql:// URL")
  if (url === developmentUrl) {
    throw new Error(
      "refusing to run: --production-url equals DATABASE_URL, which must be the development database",
    )
  }
  return { url, apply: args.yes === true }
}

/// <reference types="bun" />
import { describe, expect, test } from "bun:test"

import { pendingTags, resolveProductionRun } from "@/lib/db/migrations"

const prod = "postgresql://app:pw@prod.example.com:5432/app"
const dev = "postgresql://postgres:postgres@localhost:5432/app"

describe("resolveProductionRun", () => {
  test("refuses without an explicit production url", () => {
    expect(() => resolveProductionRun({}, dev)).toThrow("--production-url")
    expect(() => resolveProductionRun({ yes: true }, dev)).toThrow("--production-url")
  })

  test("refuses a url that is not postgres", () => {
    expect(() => resolveProductionRun({ "production-url": "mysql://x/y" }, dev)).toThrow("postgres")
  })

  test("refuses the development database even with --yes", () => {
    expect(() => resolveProductionRun({ "production-url": dev, yes: true }, dev)).toThrow(
      "development database",
    )
  })

  test("defaults to a dry run and applies only with --yes", () => {
    expect(resolveProductionRun({ "production-url": prod }, dev)).toEqual({
      url: prod,
      apply: false,
    })
    expect(resolveProductionRun({ "production-url": prod, yes: true }, dev).apply).toBe(true)
  })
})

describe("pendingTags", () => {
  const journal = {
    entries: [
      { tag: "0000_a", when: 100 },
      { tag: "0001_b", when: 200 },
      { tag: "0002_c", when: 300 },
    ],
  }

  test("lists entries not applied yet, in journal order", () => {
    expect(pendingTags(journal, [100])).toEqual(["0001_b", "0002_c"])
  })

  test("is empty when everything is applied", () => {
    expect(pendingTags(journal, [100, 200, 300])).toEqual([])
  })

  test("lists everything for a database with no history", () => {
    expect(pendingTags(journal, [])).toEqual(["0000_a", "0001_b", "0002_c"])
  })
})
